const ins = $('Candidate Models').all();
return $input.all().map((it, i) => {
  const model = ins[i] ? ins[i].json.model : '?';
  const raw = String(it.json.output || it.json.error || JSON.stringify(it.json)).slice(0, 1500);
  let j = null; try { j = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) {}
  let pts = 0; const notes = [];
  if (!j) notes.push('no valid JSON');
  else {
    if (Array.isArray(j.charge_now) && j.charge_now.length === 0) pts++; else notes.push('charge_now wrong');
    const fo = JSON.stringify(j.free_offers || '').toLowerCase(); if (fo.includes('chat') && fo.includes('deal')) pts++; else notes.push('free_offers wrong');
    if (Number(j.botbhai_monthly_inr) === 1499) pts++; else notes.push('price wrong');
    const bl = JSON.stringify(j.botbhai_blockers || ''); if (bl.includes('C02') && bl.includes('C14')) pts++; else notes.push('blockers wrong');
    if (JSON.stringify(j.never_sold || '').toLowerCase().includes('trading')) pts++; else notes.push('never_sold wrong');
  }
  return { json: { model, score: pts + '/5', notes: notes.join('; '), sample: raw.slice(0, 300) } };
});
